import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 22 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"22","title":"Page 22 | Home","prev":"/page/21/","next":"/page/23/","posts":[{"title":"Web离线的解决方案","url":"/posts/2018-07-06-offline-web/","date":"2018-07-06 23:25","tags":["web","offline"],"html":"<p>最近的工作是做嵌入在 iOS 程序内部的页面，其中有一个需求就是需要满足在离线的情况下显示页面。当然，现在主流的离线方式是使用 Service Worker 来完成离线需求。\\n但是 iOS 内置的 WKWebView 并不支持最新的 Service Worker（取决于 iOS 版本）最新版本已经支持，所以不得不想办法来解决。</p>\\n<h2 id=\\"application-cache\\" tabindex=\\"-1\\">Application Cache <a class=\\"header-anchor\\" href=\\"#application-cache\\" aria-label=\\"Permalink to &quot;Application Cache&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>AppCache 是一个过时的技术，但是在 iOS 下勉强还能用。不过 Chrome 对这种过时的技术支持不是很好，单个缓存文件最大只支持 5MB。而且还有请求的 BUG:<a href=\\"https://bugs.chromium.org/p/chromium/issues/detail?id=140445\\" target=\\"_blank\\" rel=\\"noreferrer\\">Accept header on GET request for appcache manifest</a>。触发 AppCache 是在 html 标签中添加 manifest 属性。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#6F42C1\\"> manifest</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"manifest.appcache\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ...</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>通过<code>manifest.appcache</code>文件来定义需要缓存的文件，不过载入<code>manifest.appcache</code>的页面会被作为<code>Master entries</code>缓存起来。因为 AppCache 出现的时候还是以静态网站为主，所以并不能缓存请求的 Ajax 数据。我们需要自己再手动实现缓存所有请求在<code>localStorage</code>，但是<code>localStorage</code>同样也有最大 5MB 的限制。所以也需要考虑相应的解决方案。不过，我最终采取的方式是通过嵌入<code>iframe</code>来实现触发 AppCache，这样做的好处是因为 SPA 应用是自己来控制路由的，所以导致每个路径都会保存一份<code>Master entries</code>。但是通过 iframe 的话，我们的<code>Master entries</code>永远只有一份。并且当前页面的所有资源也被顺利缓存，因为 SPA 无论访问哪个路径返回的都是相同的<code>index.html</code>。由 JS 来控制路由并加载相应的组件。</p>\\n<p>这里要补充的一点是，针对 https 的 Application Cache 是无法完成跨域请求的，所以请慎重。</p>\\n<h2 id=\\"workbox\\" tabindex=\\"-1\\">WorkBox <a class=\\"header-anchor\\" href=\\"#workbox\\" aria-label=\\"Permalink to &quot;WorkBox&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Service Worker 是现在主流的缓存技术，会帮你缓存所有的静态文件和数据请求。但是对于 SPA 项目，我们不可能自己手动书写缓存清单。所以还是借助现有的开源解决方案，这里最出名的解决方案是谷歌的 Workbox。通过使用 Webpack 插件和简单的配置，我们便可以做到缓存所有的静态资源和数据。Service Worker 有很多种缓存策略可以选择，例如 Cache First 和 NetWork First。但是 AppCache 每次都会优先使用缓存，然后再去更新最新的文件。所以我们不得不在发生更新的时候去重新加载页面。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>最终的解决方案是优先使用 Service Worker，当不支持 Service Worker 的时候再回退到 AppCache。但是想要从 AppCache 升级到 Service Worker 的时候，必须清除所有 AppCache 的所有数据。浏览器并没有提供相应的接口，我们目前采用的方式是手动删除 AppCache 储存的数据库来完成这一需求。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Using_the_application_cache\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using the application cache</a></p>\\n<p><a href=\\"https://developer.apple.com/library/archive/documentation/iPhone/Conceptual/SafariJSDatabaseGuide/OfflineApplicationCache/OfflineApplicationCache.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTML5 Offline Application Cache</a></p>\\n<p><a href=\\"https://github.com/lettertwo/appcache-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Application Cache plugin for Webpack</a></p>\\n<p><a href=\\"https://developers.google.com/web/tools/workbox/modules/workbox-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Workbox webpack Plugins</a></p>\\n<p><a href=\\"https://appcachefacts.info/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Appcache Facts</a></p>\\n"},{"title":"如何封装第三方vue组件","url":"/posts/2018-05-29-wrapper-vue-component/","date":"2018-05-29 23:19","tags":["js","vue"],"html":"<p>终于算是正式接触 SPA 的前端工作了，最近在解决很多 Vue 组件的问题，其中就有一个针对第三方组件的定制化需求，花了不少时间来折腾。</p>\\n<h2 id=\\"解决-v-model-绑定\\" tabindex=\\"-1\\">解决 v-model 绑定 <a class=\\"header-anchor\\" href=\\"#解决-v-model-绑定\\" aria-label=\\"Permalink to &quot;解决 v-model 绑定&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这次封装的就是 element 的前端 vue 框架，因为框架本身对 iOS 兼容性不好，所以需要二次封装。封装的是一个 select 组件。所以需要数据的双向绑定，官方教程也已经解释了。\\n<a href=\\"https://vuejs.org/v2/guide/components-custom-events.html#Customizing-Component-v-model\\" target=\\"_blank\\" rel=\\"noreferrer\\">v-model</a> 本质上就是绑定一个值和监听相应的事件。\\n这次本质是封装的一个 input 元素，所以我们需要手动绑定 value 和监听事件。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>官方文档也解释了这个内置变量的用法<a href=\\"https://vuejs.org/v2/api/#vm-listeners\\" target=\\"_blank\\" rel=\\"noreferrer\\">vm-listeners</a></p>\\n<h2 id=\\"继承父元素的属性\\" tabindex=\\"-1\\">继承父元素的属性 <a class=\\"header-anchor\\" href=\\"#继承父元素的属性\\" aria-label=\\"Permalink to &quot;继承父元素的属性&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>父元素的属性继承可以使用<code>v-bind=&quot;$attrs&quot;</code>来完成。所以完成组建的透明封装只需要加上三个指令。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$attrs\\"</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>虽然知道答案之后很简单，但是探索的过程中还是比较花时间的。希望能帮助大家解决这个问题，如果有什么疏漏之处，也请大家指正。</p>\\n"},{"title":"JavaScript开发中的性能优化","url":"/posts/2018-04-25-javascript-performance/","date":"2018-04-25 23:22","tags":["js","performance"],"html":"<p>最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！</p>\\n<h2 id=\\"使用-requestanimationframe-来更新动画\\" tabindex=\\"-1\\">使用 requestAnimationFrame 来更新动画 <a class=\\"header-anchor\\" href=\\"#使用-requestanimationframe-来更新动画\\" aria-label=\\"Permalink to &quot;使用 requestAnimationFrame 来更新动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用<code>requestAnimationFrame</code>把动画渲染交给浏览器，可以保证渲染保持在 60FPS。应该避免使用<code>setTimeout</code>或者<code>setInterval</code>来实现动画，因为计时器和事件队列会消耗更多的资源，还会导致无用的页面重新绘制。</p>\\n<h2 id=\\"使用-web-workers-来进行复杂的运算\\" tabindex=\\"-1\\">使用 Web Workers 来进行复杂的运算 <a class=\\"header-anchor\\" href=\\"#使用-web-workers-来进行复杂的运算\\" aria-label=\\"Permalink to &quot;使用 Web Workers 来进行复杂的运算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以把单纯的计算放在 Web Workers 中，这样不影响主页面的渲染和流畅，例如加密和矩阵变换的运算就可以完全放在 Web Workers 中来减少主线程的执行时间，避免浏览器渲染堵塞。</p>\\n<h2 id=\\"避免微优化-javascript\\" tabindex=\\"-1\\">避免微优化 JavaScript <a class=\\"header-anchor\\" href=\\"#避免微优化-javascript\\" aria-label=\\"Permalink to &quot;避免微优化 JavaScript&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>举个最简单的例子，我曾经在一本书上看到过一个提升程序效率的例子。大致是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>这里的<code>array.length</code>获取数组的长度，每次都要计算数组长度会消耗不少时间，优化之后的代码是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>通过缓存数组的长度来保证只计算一次。这就是典型的微优化，说实话这段代码我一直在用，直到最近读了其他的书才发现，现在的 JS 解释器早就优化了对数组长度的计算。无论是读取一次还是一万次消耗的时间都没有太大差别。微优化应该是 JS 引擎需要做的事情，我们不应该在实际开发中在这方面耗费过多的时间。</p>\\n<h2 id=\\"滑动事件优化\\" tabindex=\\"-1\\">滑动事件优化 <a class=\\"header-anchor\\" href=\\"#滑动事件优化\\" aria-label=\\"Permalink to &quot;滑动事件优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户监听滑动事件并执行相关动画操作的时候，记得使用<code>window.requestAnimationFrame</code>来优化动画的执行。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> onScroll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">evt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // Prevent multiple rAF callbacks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scheduledAnimationFrame) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scheduledAnimationFrame </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> readAndUpdatePage</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // do something</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">addEventListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'scroll'</span><span style=\\"color:#24292E\\">, onScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br></div></div><p>参考：</p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/debounce-your-input-handlers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Debounce Your Input Handlers</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/optimize-javascript-execution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Optimize JavaScript Execution</a></p>\\n"}]},"relativePath":"page/22/index.md","filePath":"page/[page].md"}`),e={name:"page/22/index.md"};function p(l,o,r,t,c,i){return a(),n("div")}const y=s(e,[["render",p]]);export{b as __pageData,y as default};
